void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec4 prec = texelFetch(iChannel0, ivec2(fragCoord), 0);
  vec2 c = vec2(0.5 + 0.3 * cos(iTime * 4.0), 0.5 + 0.3 * sin(iTime * 4.0));
  float p = smoothstep(0.05, 0.03, length((uv - c) * vec2(iResolution.x / iResolution.y, 1.0)));
  fragColor = prec * 0.97 + vec4(p, p * 0.5, 1.0 - uv.x, 0.0) * 0.5;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  fragColor = vec4(texelFetch(iChannel0, ivec2(fragCoord), 0).rgb, 1.0);
}
